PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
ASK WHERE {
              <https://ontology.gis-data-agent.local/natural-resource/one-map/class/LandParcel> rdfs:subClassOf <https://ontology.gis-data-agent.local/natural-resource/one-map/class/SpatialUnit> .
              <https://ontology.gis-data-agent.local/natural-resource/one-map/class/Land> owl:disjointWith <https://ontology.gis-data-agent.local/natural-resource/one-map/class/SpatialUnit> .
              <https://ontology.gis-data-agent.local/natural-resource/one-map/property/spatiallyRepresents> a owl:FunctionalProperty ;
                rdfs:domain <https://ontology.gis-data-agent.local/natural-resource/one-map/class/LandParcel> ;
                rdfs:range <https://ontology.gis-data-agent.local/natural-resource/one-map/class/Land> ;
                owl:inverseOf <https://ontology.gis-data-agent.local/natural-resource/one-map/property/representedBySpatialUnit> .
            }

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
ASK WHERE {
              <https://ontology.gis-data-agent.local/natural-resource/one-map/class/LandUseTransition> rdfs:subClassOf ?parcelRestriction, ?sourceRestriction, ?targetRestriction .
              ?parcelRestriction a owl:Restriction ; owl:onProperty <https://ontology.gis-data-agent.local/natural-resource/one-map/property/affectsParcel> ;
                owl:onClass <https://ontology.gis-data-agent.local/natural-resource/one-map/class/LandParcel> ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger .
              ?sourceRestriction a owl:Restriction ; owl:onProperty <https://ontology.gis-data-agent.local/natural-resource/one-map/property/hasSourceState> ;
                owl:onClass <https://ontology.gis-data-agent.local/natural-resource/one-map/class/LandUseState> ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger .
              ?targetRestriction a owl:Restriction ; owl:onProperty <https://ontology.gis-data-agent.local/natural-resource/one-map/property/hasTargetState> ;
                owl:onClass <https://ontology.gis-data-agent.local/natural-resource/one-map/class/LandUseState> ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger .
            }

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
ASK WHERE {
              FILTER NOT EXISTS {
                ?class a owl:Class .
                FILTER(STRSTARTS(STR(?class), "https://ontology.gis-data-agent.local/natural-resource/one-map/class/"))
                FILTER NOT EXISTS { ?class <https://ontology.gis-data-agent.local/natural-resource/one-map/reviewDisposition> ?disposition }
              }
              FILTER NOT EXISTS {
                ?class a owl:Class .
                FILTER(STRSTARTS(STR(?class), "https://ontology.gis-data-agent.local/natural-resource/one-map/class/"))
                FILTER NOT EXISTS { ?class <https://ontology.gis-data-agent.local/natural-resource/one-map/evidenceStatus> ?status }
              }
            }

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
ASK WHERE {
              FILTER NOT EXISTS {
                ?class a owl:Class ; skos:prefLabel ?label .
                FILTER(STRSTARTS(STR(?class), "https://ontology.gis-data-agent.local/natural-resource/one-map/class/"))
                FILTER(STR(?label) IN ("智能问数", "GIS Data Agent", "模型包"))
              }
            }
